<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher} from 'svelte';
 import {installationPublicUrl} from '$lib/utils/installation-origin';
 import {CustomerApiClient,CustomerApiError,SCOPES,type Scope,type TokenRecord,type ApiBot} from './customer-api-client';
 export let actorId:string;export let companyId:string;export let accessSignal:AbortSignal;
 const dispatch=createEventDispatcher<{denied:{status:number};close:void}>();
 let client:CustomerApiClient|undefined,watched:AbortSignal|undefined,mounted=false,scopeKey='',generation=0,sessionSnapshot='';
 let tokens:TokenRecord[]=[],bots:ApiBot[]=[],loading=true,busy=false,available=false,error='',notice='',secret='',copied=false;
 let name='',days='30',access:'selected'|'all_owned'='selected',selected:string[]=[],scopes:Scope[]=['bots:read','messages:send','runs:read'];
 let creating=false,revoke:TokenRecord|null=null,tab:'tokens'|'guide'='tokens';
 const labels:Record<Scope,string>={'bots:read':'List available bots','conversations:read':'Read conversation history','messages:send':'Send messages','runs:read':'Read run status and results','runs:cancel':'Cancel runs'};
 const date=(n:number|null)=>n===null?'Never':new Date(n*1000).toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'});
 $: if(mounted&&(scopeKey!==actorId+'\0'+companyId||watched!==accessSignal)){reset();scopeKey=actorId+'\0'+companyId;watched=accessSignal;watched.addEventListener('abort',lost,{once:true});if(watched.aborted)lost();else{sessionSnapshot=localStorage.getItem('token')||'';client=new CustomerApiClient(()=>localStorage.getItem('token')||'');void load();}}
 function clearSecret(){secret='';copied=false;}
 function reset(){generation++;client?.close();client=undefined;sessionSnapshot='';watched?.removeEventListener('abort',lost);clearSecret();tokens=[];bots=[];name='';selected=[];scopes=['bots:read','messages:send','runs:read'];creating=false;revoke=null;busy=false;available=false;error='';notice='';}
 function lost(){reset();loading=false;dispatch('close');}
 function failure(cause:unknown){if(cause instanceof CustomerApiError&&(cause.status===401||cause.status===403)){reset();dispatch('denied',{status:cause.status});return;}error=cause instanceof Error?cause.message:'Customer API could not be reached.';}
 async function load(){const n=generation,current=client;if(!current)return;loading=true;error='';try{const [list,directory]=await Promise.all([current.list(),current.bots()]);if(n!==generation)return;tokens=list;bots=directory;available=true;}catch(e){if(n===generation){available=false;failure(e);}}finally{if(n===generation)loading=false;}}
 async function create(){if(busy||!client||!name.trim()||!scopes.length||access==='selected'&&!selected.length)return;const n=generation,current=client;busy=true;error='';notice='';clearSecret();try{const result=await current.create({name:name.trim(),expiresAt:Math.floor(Date.now()/1000)+Number(days)*86400,scopes:[...scopes],botAccess:access==='all_owned'?{mode:'all_owned'}:{mode:'selected',botIds:[...selected]}});if(n!==generation)return;tokens=[...tokens,result.record];secret=result.secret;creating=false;name='';selected=[];notice='Token created. Save it securely before leaving this page.';}catch(e){if(n===generation)failure(e);}finally{if(n===generation)busy=false;}}
 async function confirmRevoke(){if(!revoke||!client||busy)return;const target=revoke,n=generation,current=client;busy=true;error='';try{await current.revoke(target.id);if(n!==generation)return;tokens=tokens.map(t=>t.id===target.id?{...t,revokedAt:Math.floor(Date.now()/1000)}:t);revoke=null;clearSecret();notice='Token revoked. Requests using it will be rejected.';}catch(e){if(n===generation)failure(e);}finally{if(n===generation)busy=false;}}
 async function copySecret(){const n=generation;try{await navigator.clipboard.writeText(secret);if(n===generation)copied=true;}catch{if(n===generation)error='Copy was unavailable. Select and copy the token directly.';}}
 function sessionChanged(e:StorageEvent){if(e.key==='token'||e.key===null)lost();}
 function sessionCheck(){if(client&&sessionSnapshot!==(localStorage.getItem('token')||''))lost();}
 function focusCheck(){sessionCheck();if(client)void load();}
 onMount(()=>{mounted=true;window.addEventListener('storage',sessionChanged);window.addEventListener('focus',focusCheck);const timer=setInterval(sessionCheck,500);return()=>clearInterval(timer);});
 onDestroy(()=>{reset();window.removeEventListener('storage',sessionChanged);window.removeEventListener('focus',focusCheck);});
 const customerApiBase=installationPublicUrl('/api/customer/v1');
 const catalogue=customerApiBase?`curl ${customerApiBase}/models \
  -H "Authorization: Bearer $STARLI_API_TOKEN"`: "Customer API public origin is not configured. Use HTTPS or a literal-loopback installation.";
 const example=customerApiBase?`curl -N ${customerApiBase}/chat/completions \
  -H "Authorization: Bearer $STARLI_API_TOKEN" \
  -H "Content-Type: application/json" \
  -H "Idempotency-Key: one-unique-key-per-message" \
  -d '{
    "model": "starli/<id-from-models>",
    "messages": [{"role": "user", "content": "Summarize our next steps."}],
    "stream": true
  }'`:"Customer API public origin is not configured. Use HTTPS or a literal-loopback installation.";
</script>
<section class="api" aria-label="Customer API">
 <button class="back" on:click={()=>{clearSecret();dispatch('close');}}>← Back to workspace</button>
 <header><div><div class="eyebrow">DEVELOPER ACCESS</div><h1>API</h1><p>Bring your Starli bots into your own tools.</p></div><span class="version">Customer API · v1</span></header>
 <div class="context"><span class="context-icon" aria-hidden="true">↗</span><div><strong>One bot. One conversation.</strong><p>API messages use the bot’s existing Starli conversation, memory and configured execution. Initialize its conversation in Starli before sending your first API message.</p></div></div>
 <nav aria-label="API sections"><button class:active={tab==='tokens'} on:click={()=>tab='tokens'}>Access tokens</button><button class:active={tab==='guide'} on:click={()=>{clearSecret();tab='guide';}}>Quick start</button></nav>
 {#if error}<div class="alert" role="alert">{error}</div>{/if}{#if notice}<p class="notice" role="status">{notice}</p>{/if}
 {#if tab==='tokens'}
 <div class="section-head"><div><h2>Your access tokens</h2><p>Tokens belong to your account. Choose exactly which bots and actions they can access.</p></div><div class="actions"><button disabled={busy||loading} on:click={()=>{clearSecret();void load();}}>Refresh</button><button class="primary" disabled={!available||busy||loading||!!secret} on:click={()=>{creating=!creating;revoke=null;}}>Create token</button></div></div>
 {#if secret}<div class="secret" role="region" aria-label="New API token"><h3>Save your token now</h3><p>This is the only time the full token is shown. Keep it in your secret manager and use it only from trusted server code.</p><code class="secret-value">{secret}</code><div class="actions"><button on:click={copySecret}>{copied?'Copied':'Copy token'}</button><button class="primary" on:click={()=>{clearSecret();notice='Token saved. Its full value cannot be shown again.';}}>I have saved it</button></div></div>{/if}
 {#if creating}<form class="create" on:submit|preventDefault={create}><div class="section-head"><h3>Create an access token</h3><button type="button" disabled={busy} on:click={()=>creating=false}>Cancel</button></div><div class="fields"><label>Token name<input bind:value={name} maxlength="100" placeholder="e.g. Reporting service" autocomplete="off" disabled={busy} required/></label><label>Expires in<select bind:value={days} disabled={busy}><option value="7">7 days</option><option value="30">30 days</option><option value="90">90 days</option><option value="365">365 days</option></select></label></div><fieldset disabled={busy}><legend>Permissions</legend><div class="checks">{#each SCOPES as scope}<label class="check"><input type="checkbox" bind:group={scopes} value={scope}/><span>{labels[scope]}<small>{scope}</small></span></label>{/each}</div></fieldset><fieldset disabled={busy}><legend>Bot access</legend><label class="check"><input type="radio" bind:group={access} value="selected"/><span>Selected bots<small>Explicit access to personal or shared bots.</small></span></label><label class="check"><input type="radio" bind:group={access} value="all_owned"/><span>All personal bots<small>Includes future personal bots. Shared company bots require selected access.</small></span></label>{#if access==='selected'}<div class="bot-list">{#each bots as bot}<label class="check"><input type="checkbox" bind:group={selected} value={bot.id}/><span>{bot.name}<small>{bot.companyId?'Shared company bot':'Personal bot'} · {bot.id}</small></span></label>{:else}<p>No accessible bots. Create a bot in Starli first.</p>{/each}</div>{/if}</fieldset><footer><p>Access is checked against your current account and company permissions on every request.</p><button class="primary" disabled={busy||!name.trim()||!scopes.length||access==='selected'&&!selected.length}>{busy?'Creating…':'Create token'}</button></footer></form>{/if}
 {#if loading}<p class="empty" role="status">Loading API access…</p>{:else if !available}<div class="empty"><h3>Customer API unavailable</h3><p>This deployment has not exposed a verified customer API. Token creation is unavailable until the service is enabled.</p><button on:click={()=>void load()}>Try again</button></div>{:else}<div class="token-list">{#each [...tokens].reverse() as token}<article><div class="token-top"><div><strong>{token.name}</strong><span class:revoked={token.revokedAt!==null||token.expiresAt<=Date.now()/1000} class="status">{token.revokedAt!==null?'Revoked':token.expiresAt<=Date.now()/1000?'Expired':'Active'}</span></div>{#if token.revokedAt===null&&token.expiresAt>Date.now()/1000}<button class="danger" disabled={busy} on:click={()=>{revoke=token;clearSecret();}}>Revoke</button>{/if}</div><p>{token.botAccess.mode==='all_owned'?'All personal bots':token.botAccess.botIds.length+' selected bot(s)'} · Expires {date(token.expiresAt)} · Last used {date(token.lastUsedAt)}</p><div class="scope-tags">{#each token.scopes as scope}<span>{scope}</span>{/each}</div>{#if revoke?.id===token.id}<div class="confirm" role="group" aria-label="Confirm token revocation"><strong>Revoke “{token.name}”?</strong><p>Apps using this token will lose access immediately. This cannot be undone.</p><div class="actions"><button disabled={busy} on:click={()=>revoke=null}>Keep token</button><button class="danger" disabled={busy} on:click={confirmRevoke}>{busy?'Revoking…':'Confirm revocation'}</button></div></div>{/if}</article>{:else}<div class="empty"><h3>No access tokens yet</h3><p>Create a token to connect your own service to Starli.</p></div>{/each}</div>{/if}
 {:else}
 <div class="guide"><h2>Connect to your existing bots</h2><p>Base URL <code>{customerApiBase||'Unavailable: public origin requires HTTPS or literal-loopback HTTP'}</code>. Use HTTPS (or literal-loopback HTTP for a local installation) and pass your customer token in the Authorization header. Never put credentials in URLs or browser code.</p><h3>1. Choose an accessible bot</h3><p>Create a token with <code>bots:read</code>, <code>messages:send</code> and <code>runs:read</code>. List models and copy the exact returned model ID, including its <code>starli/</code> prefix.</p><pre><code>{catalogue}</code></pre><h3>2. Send one new message</h3><p>Replace the model placeholder below with a returned ID. Send exactly one text message with role <code>user</code>. Starli owns the conversation history and uses the bot’s current provider, configuration and memory. This endpoint cannot create conversations.</p><pre><code>{example}</code></pre><h3>OpenAI-compatible streaming</h3><p>Configure an OpenAI-compatible client with this base URL, your customer token, a returned model ID and <code>stream: true</code>. The response uses server-sent <code>chat.completion.chunk</code> data with <code>choices[0].delta.content</code>, a finish reason and <code>[DONE]</code>. Streaming errors can arrive inside the event stream.</p><p>Only <code>model</code>, <code>messages</code>, <code>stream</code> and optional <code>starli.expectedCurrentId</code> are accepted. System messages, supplied history, generation parameters and tool definitions are unsupported. Text is limited to 32 KiB; shared company turns accept up to 16,000 UTF-8 bytes.</p><h3>Continue safely after an interruption</h3><p>Use a unique <code>Idempotency-Key</code> for each new message. Reuse the same key for the same submission. Save the <code>X-Starli-Operation-ID</code> response header and read its operation status if the response is interrupted or uncertain. Do not submit a new key to restart unconfirmed work. Disconnecting the stream does not cancel the native run.</p><div class="endpoints"><div><code>GET /operations/{'{operationId}'}</code><span>Resolve submission and retrieve its run ID</span></div><div><code>GET /runs/{'{runId}'}</code><span>Read current run status</span></div><div><code>GET /runs/{'{runId}'}/result</code><span>Read final result · 202 while still running</span></div><div><code>POST /runs/{'{runId}'}/cancel</code><span>Request a stop · requires runs:cancel</span></div><div><code>GET /bots/{'{botId}'}/messages</code><span>Read canonical history · requires conversations:read</span></div></div><p>A busy conversation or stale parent can return 409. If a bot is uninitialized, initialize it in Starli. A configured provider may be unsupported by this API; its settings are kept intact. Token access never adds permissions beyond your current Starli access.</p></div>
 {/if}
</section>
<style>
 .api{font-family:'Mona Sans',sans-serif;width:100%;max-width:1050px;margin:0 auto;padding:36px 44px 70px;color:#17243f;overflow:auto}button,input,select{font:inherit;font-size:12px}button{border:1px solid #e6ebf4;background:white;border-radius:8px;padding:9px 13px;color:#17243f;cursor:pointer;white-space:nowrap}button:disabled{opacity:.45;cursor:default}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid #9ab5ff;outline-offset:3px}.back{border:0;padding:0;color:#71809a;background:none}.primary{background:#3466f6;border-color:#3466f6;color:white}.danger{color:#a53f4a;border-color:#ecd9dc}header{display:flex;align-items:center;justify-content:space-between;gap:20px;margin:32px 0 25px}.eyebrow{font-size:9px;letter-spacing:1.4px;color:#71809a;margin-bottom:10px}h1{font-size:30px;font-weight:500;letter-spacing:-1px;margin:0}h2{font-size:17px;font-weight:550;margin:0}h3{font-size:14px;font-weight:550;margin:0}p{font-size:12px;line-height:1.75;color:#71809a;margin:6px 0}strong{font-size:13px;font-weight:550}.version{font-size:10px;color:#71809a;background:#f6f8fc;padding:7px 11px;border-radius:6px}.context{display:flex;gap:14px;background:#f6f8fc;border:1px solid #e6ebf4;border-radius:12px;padding:18px 20px}.context-icon{display:grid;place-items:center;border-radius:9px;background:#eaf0ff;width:32px;height:32px;flex-shrink:0;color:#3466f6}.context p{max-width:720px;margin-bottom:0}nav{display:flex;gap:25px;border-bottom:1px solid #e6ebf4;margin:25px 0}nav button{border:0;border-radius:0;color:#71809a;padding:13px 0;background:none;border-bottom:2px solid transparent}nav button.active{color:#3466f6;border-bottom-color:#3466f6}.section-head,.token-top,footer{display:flex;justify-content:space-between;align-items:center;gap:16px}.section-head{margin:20px 0}.actions{display:flex;gap:8px;flex-wrap:wrap}.create,.secret{border:1px solid #e6ebf4;border-radius:12px;padding:22px;margin:20px 0;background:#fff}.create .section-head{margin:0 0 20px}.secret{background:#f6f8fc;border-color:#bdceff}.secret-value{display:block;overflow-wrap:anywhere;user-select:all;background:white;border:1px solid #e6ebf4;padding:14px;border-radius:8px;margin:15px 0}.fields{display:grid;grid-template-columns:2fr 1fr;gap:18px}label{font-size:12px}input:not([type=checkbox]):not([type=radio]),select{display:block;width:100%;color:#17243f;border:1px solid #e6ebf4;background:white;border-radius:8px;padding:10px 12px;margin-top:8px}fieldset{border:0;margin:22px 0;padding:0}legend{font-size:12px;font-weight:550;margin-bottom:12px}.checks{display:grid;grid-template-columns:1fr 1fr;gap:10px}.check{display:flex;align-items:flex-start;gap:9px;margin:8px 0;cursor:pointer}.check input{accent-color:#3466f6;margin-top:3px}.check small{display:block;color:#71809a;font-size:10px;line-height:1.7;overflow-wrap:anywhere}.bot-list{max-height:230px;overflow:auto;padding:6px 12px;margin-top:12px;border:1px solid #e6ebf4;border-radius:8px}footer{border-top:1px solid #e6ebf4;padding-top:15px}footer p{max-width:500px;font-size:11px}.token-list{border:1px solid #e6ebf4;border-radius:12px;overflow:hidden;margin-top:20px}article{padding:20px 22px;border-bottom:1px solid #e6ebf4}article:last-child{border-bottom:0}.status{font-size:9px;color:#17846c;background:#eef8f4;padding:4px 7px;border-radius:5px;margin-left:10px}.status.revoked{color:#71809a;background:#f6f8fc}.scope-tags{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}.scope-tags span{background:#f6f8fc;font-size:9px;color:#71809a;border-radius:5px;padding:4px 7px}.confirm{padding:16px;background:#fcf6f6;border:1px solid #ecd9dc;border-radius:9px;margin-top:15px}.confirm .actions{margin-top:12px}.empty{text-align:center;padding:44px 18px;background:#fafbfd;border:1px solid #e6ebf4;border-radius:12px}.empty button{margin-top:14px}.token-list .empty{border:0}.alert{font-size:12px;padding:13px 16px;border:1px solid #ecd9dc;background:#fcf6f6;color:#a53f4a;border-radius:8px;margin:15px 0}.notice{color:#17846c}.guide{max-width:780px}.guide h3{margin:27px 0 10px}.guide>p{line-height:1.9}code{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:11px}p code{color:#3466f6;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f6f8fc;border:1px solid #e6ebf4;border-radius:10px;padding:18px;margin:15px 0;line-height:1.9}.endpoints{border:1px solid #e6ebf4;border-radius:10px;margin:18px 0;padding:3px 17px}.endpoints>div{padding:12px 0;border-bottom:1px solid #e6ebf4;display:flex;flex-direction:column;gap:5px}.endpoints>div:last-child{border:0}.endpoints span{font-size:11px;color:#71809a}@media(max-width:700px){.api{padding:26px 22px}.section-head,header,footer{align-items:flex-start;flex-direction:column}.fields,.checks{grid-template-columns:1fr}.version{display:none}.create,.secret,article{padding:17px}.token-top{align-items:flex-start}h1{font-size:25px}.context{padding:16px}.context-icon{display:none}}
</style>


